import {normalize,applyContentRating} from './core.mjs';
export const titleKey=s=>normalize(s).replace(/[\p{P}\p{S}]+/gu,' ').replace(/\s+/g,' ').trim();
const titleSet=e=>[e.title,...(e.alternativeTitles??e.alternatives??[]),e.native].filter(Boolean).map(titleKey);
function authorTokens(s){return new Set(normalize(s).replace(/[^\p{L}\p{N}]+/gu,' ').split(' ').filter(Boolean));}
function authorsAgree(a,b){if(!a||!b)return null;const x=authorTokens(a),y=authorTokens(b);if(!x.size||!y.size)return null;const overlap=[...x].filter(t=>y.has(t)).length;return overlap/Math.min(x.size,y.size)>=.8;}
function similarity(a,b){const x=new Set(a.split(' ')),y=new Set(b.split(' '));const common=[...x].filter(t=>y.has(t)).length;return 2*common/(x.size+y.size);}
export function rankCandidates(entry,candidates){const titles=titleSet(entry);return [...new Map(candidates.filter(c=>Number.isInteger(c.id)&&c.id>0).map(c=>[c.id,c])).values()].map(c=>{const other=titleSet(c),exact=titles.some(t=>other.includes(t)),author=authorsAgree(entry.author,c.author);let score=exact?(author===false?.83:author===true?.99:.96):Math.max(0,...titles.flatMap(a=>other.map(b=>similarity(a,b))))*.85;if(!exact&&author===true)score=Math.min(.95,score+.1);const sourceNumbers=new Set(titles.flatMap(t=>t.match(/\d+/g)??[])),candidateNumbers=new Set(other.flatMap(t=>t.match(/\d+/g)??[]));if(sourceNumbers.size&&candidateNumbers.size&&![...sourceNumbers].some(n=>candidateNumbers.has(n)))score=Math.min(score,.6);if(['NOVEL','novel','light_novel'].includes(c.format))score=Math.min(score,.6);return {...c,score,reason:exact?(author===false?'Title matches; author differs':author?'Exact title and author':'Unique exact title'):'Similar title; review required',exact};}).sort((a,b)=>b.score-a.score);}
export function pickMatch(entry,candidates){const ranked=rankCandidates(entry,candidates),best=ranked[0];if(!best)return {ranked,confirmed:false};return {ranked,confirmed:best.exact&&best.score>=.96&&(!ranked[1]||best.score-ranked[1].score>=.08)};}
export function acceptCandidate(e,c,reason='High · automatic match'){Object.assign(e,{mediaId:c.id,matchedTitle:c.title,matchConfirmed:true,confidence:reason,totalChapters:c.chapters??null,totalVolumes:c.volumes??null,anilistId:c.anilistId??e.anilistId,malId:c.malId??e.malId,matchState:'Matched',matchError:''});applyContentRating(e,c);}
export function matchSummary(entries){const a=entries.filter(e=>e.included);return {total:a.length,matched:a.filter(e=>e.matchConfirmed).length,pending:a.filter(e=>!e.matchConfirmed&&(!e.matchState||['Pending','Error'].includes(e.matchState))).length,uncertain:a.filter(e=>!e.matchConfirmed&&e.matchState==='Uncertain').length,notFound:a.filter(e=>!e.matchConfirmed&&e.matchState==='NotFound').length,errors:a.filter(e=>e.matchState==='Error').length};}
export async function matchLibrary(entries,api,{destination='AniList',signal,progress=()=>{},retryUnresolved=false,cache=new Map()}={}){let requests=0,consecutiveErrors=0;const started=Date.now();const report=()=>progress({...matchSummary(entries),requests,elapsedMs:Date.now()-started});for(const e of entries){signal?.throwIfAborted();e.anilistId??=e.trackers?.find(t=>t.service===2)?.mediaId??null;e.malId??=e.trackers?.find(t=>t.service===1)?.mediaId??null;if(!e.included||e.matchConfirmed)continue;if(!retryUnresolved&&['Uncertain','NotFound'].includes(e.matchState))continue;e.matchState='Pending';e.matchError='';report();try{const crossId=destination==='AniList'?e.malId:e.anilistId;if(crossId&&api.lookup){const key=`${destination}:id:${crossId}`;let c=cache.get(key);if(c===undefined){requests++;try{c=await api.lookup({service:destination==='AniList'?'MyAnimeList':'AniList',id:crossId},signal);cache.set(key,c??null);}catch(error){if(signal?.aborted)throw error;c=null;}}if(c){acceptCandidate(e,c,'High · linked platform ID');report();continue;}}
const queries=[...new Set([e.title,...e.alternativeTitles].map(t=>String(t).trim()).filter(t=>t.length>=2))].slice(0,4);const candidates=[];e.matchQueries??=[];for(const query of queries){signal?.throwIfAborted();const key=destination+':title:'+titleKey(query);let found=cache.get(key);if(!found){requests++;found=await api.search(query,signal);cache.set(key,found);}candidates.push(...found);if(!e.matchQueries.includes(query))e.matchQueries.push(query);const choice=pickMatch(e,candidates);e.matchCandidates=choice.ranked.slice(0,5);if(choice.confirmed){acceptCandidate(e,choice.ranked[0]);break;}}
if(!e.matchConfirmed){const best=pickMatch(e,candidates).ranked[0];e.matchState=best?'Uncertain':'NotFound';e.confidence=best?'Uncertain · '+Math.round(best.score*100)+'%':'No match found';e.mediaId=best?best.id:null;e.matchedTitle=best?best.title:'';applyContentRating(e,null,false);}consecutiveErrors=0;
}catch(error){if(signal?.aborted)throw error;e.matchState='Error';e.matchError=error.message||'Search failed';if(++consecutiveErrors>=3){report();throw Error('Matching paused after repeated service errors. Completed matches are kept. Check your connection or client ID, then resume.');}}report();}return matchSummary(entries);}
